def cover():
    obj = ['កំណត់បានមួយចំនួនគត់ចែកដាច់នឹង 2, 3, 4, 5, 7, 8, 9', 'បំបែកចំនួនមិនបឋមជាផលគុណកត្តាបឋម', 'រកតួចែករួមធំបំផុតនិងពហុគុណរួមតូចបំផុត', 'អនុវត្តតួចែករួមធំបំផុតនិងពហុគុណរួមតូចបំផុតក្នុងការដោះស្រាយចំណោទ ។']
    html = ('<p class="ts-kicker">ថ្នាក់ទី ៧ · មេរៀនទី ២</p><h1>តួចែកនិងពហុគុណ</h1>'
            '<div class="ts-obj"><h3>គោលបំណង</h3><ol>' + ''.join(f'<li>{o}</li>' for o in obj) + '</ol></div>')
    return {'k': 'title', 'c': 'cover', 'html': html}


def rows(items, hi, per, size=70, tail=None):
    """worked examples: the number in digit boxes (the part that matters lit up) and the division beside it; one row per press of →."""
    out = ''
    for i, (num, q) in enumerate(items):
        row = '<div class="rr">' + digits(num, hi=hi, size=size, maxh='11vh') + f'<div class="rt"><b>{m(str(num) + chr(92) + "div " + str(per) + "=" + str(q))}</b>' + (tail(num) if tail else '') + '</div></div>'
        out += rvd(i, row) if i else row
    return out


def chips(items, color, label, big=False):
    w = 96 if not big else 110
    b = ''.join(rect(10 + i * (w + 12), 10, w, 84, color, 16) + T(10 + i * (w + 12) + w / 2, 70, v, 52, '#fff') for i, v in enumerate(items))
    return fig(svg(len(items) * (w + 12) + 20, 104, b, '14vh'), label)


